def lum(h):
    c=[int(h[i:i+2],16)/255 for i in (1,3,5)]
    c=[x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4 for x in c]
    return .2126*c[0]+.7152*c[1]+.0722*c[2]
def cr(a,b):
    a,b=sorted([lum(a),lum(b)],reverse=True); return (a+.05)/(b+.05)
for c in ['#8A94A3','#7E8898','#79828F','#737D8C']: print('light',c,round(cr(c,'#F5F7FA'),2),round(cr(c,'#FFFFFF'),2))
for c in ['#5F6E84','#66768C','#6B7A90','#718199']: print('dark',c,round(cr(c,'#18202B'),2),round(cr(c,'#0F141B'),2))
"

