body {
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
}

.page {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--gap);
}

.app-header h1 {
  margin: 0;
  font-size: 1.75rem;
}

.tagline {
  margin: 4px 0 var(--gap);
  color: var(--text-muted);
}

.layout {
  display: grid;
  gap: var(--gap);
  grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
  align-items: start;
}

@media (max-width: 768px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

