      return { amount, rate, tenure, headline: head.toFixed(2), lastPayment: last.payment.toFixed(2), worstDeviation: worst.dev, atMonth: worst.month, finalBalance: last.balance.toFixed(2) };
    });
  }, [['81020318.72','3.97','204'], ['5649385.87','44.01','439'], ['1235400.38','50','238']]);
  console.table(out); await b.close();
})();"

