.history-card {
  grid-column: 1 / -1;
}

.history-card h2 {
  font-size: 1.15rem;
  margin: 0 0 8px;
}

.history-list {
  list-style: none;
  margin: 0 0 var(--gap);
  padding: 0;
  display: grid;
  gap: 8px;
}

.history-entry {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px var(--gap);
  padding: 8px 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
}

.entry-text {
  min-width: 0;
}

.entry-text p {
  margin: 0;
  overflow-wrap: anywhere;
}

.entry-line1 {
  font-weight: 600;
}

.entry-time {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.entry-actions {
  display: flex;
  gap: 8px;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
